@props(['tour', 'bars' => false])
<div class="ops-load-stats">@foreach([[$tour['total'],'Missions'],[$tour['products'],'Produits'],[$tour['weight'].' kg','Poids total'],[str_replace('.',',',(string)$tour['volume']).' m³','Volume total']] as [$value,$label])<div><strong>{{ $value }}</strong><small>{{ $label }}</small></div>@endforeach</div>
